(()=>{'use strict';const $=id=>document.getElementById(id),titles=['First contact','A different angle','Hidden frequency','Through the silence','Parallel worlds','The long way home','Prism garden','Across the void','A gentle detour','Signal in the dark','Almost a constellation','The last awakening'];let current=1,board,moves=0,busy=false,generation=0,sound=false,audio;let saved={};try{saved=JSON.parse(localStorage.getItem('echo-vault-v1')||'{}')||{}}catch{}const store=()=>{try{localStorage.setItem('echo-vault-v1',JSON.stringify(saved))}catch{}};function tone(frequency=420){if(!sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.value=frequency;g.gain.setValueAtTime(.06,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.22);o.connect(g).connect(audio.destination);o.start();o.stop(audio.currentTime+.23)}catch{}}
function levels(){ $('levels').replaceChildren();for(let i=1;i<=12;i++){const b=document.createElement('button');b.textContent=String(i).padStart(2,'0');b.className=(saved[i]!==undefined?'done ':'')+(i===current?'active':'');b.setAttribute('aria-label',`Chapter ${i}: ${titles[i-1]}${saved[i]!==undefined?', completed':''}`);b.setAttribute('aria-pressed',i===current);b.onclick=()=>load(i);$('levels').append(b)}}
function clearLight(){generation++;busy=false;$('fire').disabled=false;document.querySelectorAll('.lit,.hinted').forEach(e=>e.classList.remove('lit','hinted'));$('beam')?.remove()}
function load(n){clearLight();current=n;moves=0;board=EchoEngine.level(n);$('moves').textContent='00';$('best').textContent=saved[n]??'—';$('chapter').textContent=`CHAPTER ${String(n).padStart(2,'0')} / 12`;$('level-title').textContent=titles[n-1];$('board-size').textContent=`${board.n} × ${board.n}`;$('progress').style.width=`${Object.keys(saved).length/12*100}%`;$('status').textContent='Your signal is waiting.';$('board').style.gridTemplateColumns=`repeat(${board.n},minmax(0,1fr))`;$('board').replaceChildren();for(let id=0;id<board.n*board.n;id++){const mirror=board.mirrors[id],b=document.createElement(mirror?'button':'div');b.className='tile'+(mirror?' mirror':'')+(id===board.start?' source':id===board.finish?' finish':board.rocks.includes(id)?' rock':'');b.id='tile-'+id;b.textContent=mirror||(id===board.start?'◉':id===board.finish?'◈':board.rocks.includes(id)?'▪':'');b.setAttribute('aria-label',`Row ${Math.floor(id/board.n)+1}, column ${id%board.n+1}: ${mirror?'mirror '+(mirror==='/'?'slash':'backslash'):id===board.start?'light source':id===board.finish?'target crystal':board.rocks.includes(id)?'stone':'empty'}`);if(mirror)b.onclick=()=>{if(busy)return;clearLight();board.mirrors[id]=board.mirrors[id]==='/'?'\\':'/';b.textContent=board.mirrors[id];b.setAttribute('aria-label',`Mirror at row ${Math.floor(id/board.n)+1}, column ${id%board.n+1}: ${board.mirrors[id]==='/'?'slash':'backslash'}`);moves++;$('moves').textContent=String(moves).padStart(2,'0');$('status').textContent='A new angle. Try the signal.';tone(360+moves%5*50)};$('board').append(b)}levels()}
function beam(path){let svg=$('beam');if(!svg){svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.id='beam';svg.setAttribute('viewBox','0 0 1000 1000');svg.setAttribute('preserveAspectRatio','none');svg.setAttribute('aria-hidden','true');const p=document.createElementNS('http://www.w3.org/2000/svg','polyline');svg.append(p);$('board').append(svg)}const grid=$('board').getBoundingClientRect();const points=path.map(id=>{const r=$('tile-'+id).getBoundingClientRect(),s=svg.getBoundingClientRect();return `${(r.left+r.width/2-s.left)/s.width*1000},${(r.top+r.height/2-s.top)/s.height*1000}`}).join(' ');svg.firstChild.setAttribute('points',points)}
$('fire').onclick=async()=>{if(busy)return;clearLight();busy=true;$('fire').disabled=true;const ticket=generation,result=EchoEngine.trace(board),reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;$('status').textContent='Sending a little light into the unknown…';for(let i=0;i<result.path.length;i++){if(ticket!==generation)return;$('tile-'+result.path[i]).classList.add('lit');beam(result.path.slice(0,i+1));if(!reduced)await new Promise(r=>setTimeout(r,65))}if(ticket!==generation)return;busy=false;$('fire').disabled=false;if(result.won){saved[current]=Math.min(saved[current]??Infinity,moves);store();$('best').textContent=saved[current];$('progress').style.width=`${Object.keys(saved).length/12*100}%`;levels();$('status').textContent='Crystal awakened. The signal found its way.';tone(750);$('win-title').textContent=current===12?'You brought the stars back.':'A little light goes a long way.';$('win-text').textContent=`Chapter ${current} complete in ${moves} mirror turns. ${current===12?'Revisit any vault and try to beat your best.':'Another vault is waiting for your signal.'}`;$('next').textContent=current===12?'Start the journey again ↗':'Next chapter ↗';$('win').showModal()}else{$('status').textContent=result.reason==='rock'?'The signal hit a stone. Try a different angle.':result.reason==='loop'?'The light is caught in a loop. Break the pattern.':'The signal drifted out of the vault. Redirect a mirror.';tone(180)}};
$('reset').onclick=()=>load(current);$('hint').onclick=()=>{if(busy)return;const wrong=Object.keys(board.solution).find(id=>board.mirrors[id]!==board.solution[id]);if(wrong===undefined){$('status').textContent='The route is ready. Send the light!';return}clearLight();const b=$('tile-'+wrong);b.classList.add('hinted');$('status').textContent='Turn the highlighted mirror once. One step closer.';b.focus()};$('next').onclick=()=>{$('win').close();load(current===12?1:current+1)};$('stay').onclick=()=>$('win').close();$('sound').onclick=()=>{sound=!sound;$('sound').textContent=sound?'Sound on ♫':'Sound off ♫';$('sound').setAttribute('aria-pressed',sound);tone()};load(1);
})();
